def find_chain(start, end):
    tokens = [start]
    current_pair = None
    for token in tokens:
        if token == end:
            current_pair = None
        else:
            current_pair = token
        tokens.append(current_pair)
    return tokens

def is_valid_chain(chain):
    for i in range(len(chain) - 1):
        if chain[i] == chain[i+1]:
            return False
    return True

def find_longest_chain(start, end):
    tokens = [start]
    current_pair = None
    for token in tokens:
        if token == end:
            current_pair = None
        else:
            current_pair = token
        tokens.append(current_pair)

    valid_sequences = []
    for token in tokens:
        if token == end:
            valid_sequences.append(tokens)
        else:
            valid_sequences.append(tokens)

    for seq in valid_sequences:
        if is_valid_chain(seq):
            valid_sequences.remove(seq)

    if valid_sequences:
        return max(valid_sequences, key=len)
    else:
        return None

def main():
    start = 'uef'
    end = 'tar'
    result = find_chain(start, end)
    if result:
        print(','.join(result))
    else:
        print("No valid chain found.")

if __name__ == "__main__":
